sumArray(A, n)
BEGIN
  suma <- 0;
  FOR i <- 1 TO n DO
  BEGIN
    suma <- suma + A[i];
  END;
  RETURN suma;
END

countItems(A, n)
BEGIN
  contador <- 0;
  FOR i <- 1 TO n DO
  BEGIN
    contador <- contador + 1;
  END;
  RETURN contador;
END

sumTwoArrays(A, B, n, m)
BEGIN
  total <- 0;
  FOR i <- 1 TO n DO
  BEGIN
    total <- total + A[i];
  END;
  FOR j <- 1 TO m DO
  BEGIN
    total <- total + B[j];
  END;
  RETURN total;
END

threePasses(A, B, C, n)
BEGIN
  total <- 0;
  FOR i <- 1 TO n DO
  BEGIN
    total <- total + A[i];
  END;
  FOR j <- 1 TO n DO
  BEGIN
    total <- total + B[j];
  END;
  FOR k <- 1 TO n DO
  BEGIN
    total <- total + C[k];
  END;
  RETURN total;
END

squareDoubleLoop(A, n)
BEGIN
  total <- 0;
  FOR i <- 1 TO n DO
  BEGIN
    FOR j <- 1 TO n DO
    BEGIN
      total <- total + A[i][j];
    END;
  END;
  RETURN total;
END

rectangularDoubleLoop(A, n, m)
BEGIN
  total <- 0;
  FOR i <- 1 TO n DO
  BEGIN
    FOR j <- 1 TO m DO
    BEGIN
      total <- total + A[i][j];
    END;
  END;
  RETURN total;
END

lowerTriangular(A, n)
BEGIN
  total <- 0;
  FOR i <- 1 TO n DO
  BEGIN
    FOR j <- 1 TO i DO
    BEGIN
      total <- total + A[i][j];
    END;
  END;
  RETURN total;
END

upperTriangular(A, n)
BEGIN
  total <- 0;
  FOR i <- 1 TO n DO
  BEGIN
    FOR j <- i TO n DO
    BEGIN
      total <- total + A[i][j];
    END;
  END;
  RETURN total;
END

threeDimensionalRectangular(A, n, m)
BEGIN
  total <- 0;
  FOR i <- 1 TO n DO
  BEGIN
    FOR j <- 1 TO n DO
    BEGIN
      FOR k <- 1 TO m DO
      BEGIN
        total <- total + A[i][j][k];
      END;
    END;
  END;
  RETURN total;
END

linearThenConstant(A, n, flag)
BEGIN
  total <- 0;
  IF (flag = true) THEN
  BEGIN
    FOR i <- 1 TO n DO
    BEGIN
      total <- total + A[i];
    END;
  END
  ELSE
  BEGIN
    total <- total + 1;
  END;
  RETURN total;
END

quadraticThenLinear(A, n, flag)
BEGIN
  total <- 0;
  IF (flag = true) THEN
  BEGIN
    FOR i <- 1 TO n DO
    BEGIN
      FOR j <- 1 TO n DO
      BEGIN
        total <- total + A[i][j];
      END;
    END;
  END
  ELSE
  BEGIN
    FOR k <- 1 TO n DO
    BEGIN
      total <- total + A[k];
    END;
  END;
  RETURN total;
END

nestedIfInsideFor(A, n)
BEGIN
  total <- 0;
  FOR i <- 1 TO n DO
  BEGIN
    IF (A[i] > 0) THEN
    BEGIN
      FOR j <- 1 TO n DO
      BEGIN
        total <- total + A[j];
      END;
    END
    ELSE
    BEGIN
      total <- total + 1;
    END;
  END;
  RETURN total;
END

mergeSortCost(n)
BEGIN
  IF (n <= 1) THEN
  BEGIN
    RETURN 1;
  END
  ELSE
  BEGIN
    left <- mergeSortCost(n / 2);
    right <- mergeSortCost(n / 2);
    total <- 0;
    FOR i <- 1 TO n DO
    BEGIN
      total <- total + 1;
    END;
    RETURN left + right + total;
  END;
END

binarySearchCost(n)
BEGIN
  IF (n <= 1) THEN
  BEGIN
    RETURN 1;
  END
  ELSE
  BEGIN
    sub <- binarySearchCost(n / 2);
    RETURN sub + 1;
  END;
END

fullBinaryTraversalCost(n)
BEGIN
  IF (n <= 1) THEN
  BEGIN
    RETURN 1;
  END
  ELSE
  BEGIN
    a <- fullBinaryTraversalCost(n / 2);
    b <- fullBinaryTraversalCost(n / 2);
    RETURN a + b + 1;
  END;
END

ternarySplitCost(n)
BEGIN
  IF (n <= 1) THEN
  BEGIN
    RETURN 1;
  END
  ELSE
  BEGIN
    a <- ternarySplitCost(n / 3);
    b <- ternarySplitCost(n / 3);
    c <- ternarySplitCost(n / 3);
    total <- 0;
    FOR i <- 1 TO n DO
    BEGIN
      total <- total + 1;
    END;
    RETURN a + b + c + total;
  END;
END

karatsubaLikeCost(n)
BEGIN
  IF (n <= 1) THEN
  BEGIN
    RETURN 1;
  END
  ELSE
  BEGIN
    a <- karatsubaLikeCost(n / 2);
    b <- karatsubaLikeCost(n / 2);
    c <- karatsubaLikeCost(n / 2);
    total <- 0;
    FOR i <- 1 TO n DO
    BEGIN
      total <- total + 1;
    END;
    RETURN a + b + c + total;
  END;
END

nonlinearRecursiveArgument(n)
BEGIN
  IF (n <= 1) THEN
  BEGIN
    RETURN 1;
  END
  ELSE
  BEGIN
    sub <- nonlinearRecursiveArgument(n - n / 2);
    RETURN sub + 1;
  END;
END

factorialCost(n)
BEGIN
  IF (n <= 1) THEN
  BEGIN
    RETURN 1;
  END
  ELSE
  BEGIN
    sub <- factorialCost(n - 1);
    RETURN n * sub;
  END;
END

fibonacciCost(n)
BEGIN
  IF (n <= 1) THEN
  BEGIN
    RETURN 1;
  END
  ELSE
  BEGIN
    a <- fibonacciCost(n - 1);
    b <- fibonacciCost(n - 2);
    RETURN a + b;
  END;
END

doublePreviousCost(n)
BEGIN
  IF (n <= 0) THEN
  BEGIN
    RETURN 1;
  END
  ELSE
  BEGIN
    a <- doublePreviousCost(n - 1);
    b <- doublePreviousCost(n - 1);
    RETURN a + b;
  END;
END

recursiveLinearLocalWork(n)
BEGIN
  IF (n <= 0) THEN
  BEGIN
    RETURN 1;
  END
  ELSE
  BEGIN
    local <- 0;
    FOR i <- 1 TO n DO
    BEGIN
      local <- local + 1;
    END;
    sub <- recursiveLinearLocalWork(n - 1);
    RETURN sub + local;
  END;
END

whileLinearIncrement(n)
BEGIN
  i <- 0;
  total <- 0;
  WHILE (i < n) DO
  BEGIN
    total <- total + 1;
    i <- i + 1;
  END;
  RETURN total;
END

whileLinearDecrement(n)
BEGIN
  i <- n;
  total <- 0;
  WHILE (i > 0) DO
  BEGIN
    total <- total + 1;
    i <- i - 1;
  END;
  RETURN total;
END

whileGeometricGrowthTwo(n)
BEGIN
  i <- 1;
  total <- 0;
  WHILE (i <= n) DO
  BEGIN
    total <- total + 1;
    i <- i * 2;
  END;
  RETURN total;
END

whileGeometricShrinkTwo(n)
BEGIN
  i <- n;
  total <- 0;
  WHILE (i > 1) DO
  BEGIN
    total <- total + 1;
    i <- i / 2;
  END;
  RETURN total;
END

binarySearchIterative(A, n, objetivo)
BEGIN
  low <- 1;
  high <- n;
  encontrado <- false;
  WHILE (low <= high) DO
  BEGIN
    mid <- (low + high) DIV 2;
    IF (A[mid] = objetivo) THEN
    BEGIN
      encontrado <- true;
      low <- high + 1;
    END
    ELSE
    BEGIN
      IF (A[mid] < objetivo) THEN
      BEGIN
        low <- mid + 1;
      END
      ELSE
      BEGIN
        high <- mid - 1;
      END;
    END;
  END;
  RETURN encontrado;
END

binaryLowerBound(A, n, objetivo)
BEGIN
  low <- 1;
  high <- n;
  WHILE (low <= high) DO
  BEGIN
    mid <- (low + high) DIV 2;
    IF (A[mid] < objetivo) THEN
    BEGIN
      low <- mid + 1;
    END
    ELSE
    BEGIN
      high <- mid - 1;
    END;
  END;
  RETURN low;
END

oneShotFlag(n)
BEGIN
  activo <- true;
  pasos <- 0;
  WHILE (activo = true) DO
  BEGIN
    pasos <- pasos + 1;
    activo <- false;
  END;
  RETURN pasos;
END

linearCounterNonZeroStart(n)
BEGIN
  i <- 5;
  total <- 0;
  WHILE (i <= n) DO
  BEGIN
    total <- total + 1;
    i <- i + 1;
  END;
  RETURN total;
END

unknownExternalCondition(n)
BEGIN
  total <- 0;
  WHILE (condicionExterna()) DO
  BEGIN
    total <- total + 1;
  END;
  RETURN total;
END

missingControlUpdate(n)
BEGIN
  i <- 0;
  total <- 0;
  WHILE (i < n) DO
  BEGIN
    total <- total + 1;
  END;
  RETURN total;
END

contradictoryProgress(n)
BEGIN
  i <- 0;
  total <- 0;
  WHILE (i < n) DO
  BEGIN
    total <- total + 1;
    i <- i - 1;
  END;
  RETURN total;
END

unknownUpdateFunction(n)
BEGIN
  i <- 0;
  total <- 0;
  WHILE (i < n) DO
  BEGIN
    total <- total + 1;
    i <- actualizar(i);
  END;
  RETURN total;
END

missingEndBlock(n)
BEGIN
  total <- 0;
  FOR i <- 1 TO n DO
  BEGIN
    total <- total + i;
  RETURN total;
END

invalidAssignmentExpression(n)
