  x <- ;
  RETURN total;
END

euclidModulo(a, b)
BEGIN
  WHILE (b <> 0) DO
  BEGIN
    r <- a MOD b;
    a <- b;
    b <- r;
  END;
  RETURN a;
END

variableMultiplicativeFactor(n, k)
BEGIN
  i <- 1;
  total <- 0;
  WHILE (i < n) DO
  BEGIN
    total <- total + 1;
    i <- i * k;
  END;
  RETURN total;
END

quadraticCombineCost(n)
BEGIN
  IF (n <= 1) THEN
  BEGIN
    RETURN 1;
  END
  ELSE
  BEGIN
    a <- quadraticCombineCost(n / 2);
    b <- quadraticCombineCost(n / 2);
    total <- 0;
    FOR i <- 1 TO n DO
    BEGIN
      FOR j <- 1 TO n DO
      BEGIN
        total <- total + 1;
      END;
    END;
    RETURN a + b + total;
  END;
END

recursiveQuadraticLocalWork(n)
BEGIN
  IF (n <= 0) THEN
  BEGIN
    RETURN 1;
  END
  ELSE
  BEGIN
    local <- 0;
    FOR i <- 1 TO n DO
    BEGIN
      FOR j <- 1 TO n DO
      BEGIN
        local <- local + 1;
      END;
    END;
    sub <- recursiveQuadraticLocalWork(n - 1);
    RETURN sub + local;
  END;
END
